import { expect, expectStatus, test } from "../../fixtures";

test.describe("vendor name uniqueness", () => {
  test(
    "rejects a vendor whose name matches an existing vendor in the tenant, ignoring case",
    { tag: "@VEN-03" },
    async ({ apiAs }) => {
      // Arrange: a unique suffix keeps names distinct from other tests sharing the database.
      const member = await apiAs("member");
      const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

      const existing = await member.post("/api/vendors", {
        data: {
          name: `Acme Freight ${suffix}`,
          category: "logistics",
          contact_email: "ops@acmefreight.example",
        },
      });
      await expectStatus(existing, 201);

      // Act: same name, different casing.
      const duplicate = await member.post("/api/vendors", {
        data: {
          name: `acme freight ${suffix}`,
          category: "logistics",
          contact_email: "ops@acmefreight.example",
        },
      });

      // Assert
      const body = await expectStatus(duplicate, 409);
      expect(body.error.code).toBe("vendor_name_taken");
    },
  );
});
